require_once dirname(__DIR__).'/includes/functions.php';require_role('admin');$eventId=(int)($_GET['event']??0);$s=db()->prepare('SELECT title FROM events WHERE id=?');$s->execute([$eventId]);if(!$s->fetchColumn()){http_response_code(404);exit('Event not found.');}$s=db()->prepare('SELECT name,reg_no,department,phone,email,created_at,status FROM registrations WHERE event_id=? ORDER BY created_at');$s->execute([$eventId]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="event-'.$eventId.'-participants.csv"');$out=fopen('php://output','w');fputcsv($out,['Name','Registration ID','Department','Phone','Email','Registered At','Status']);while($r=$s->fetch()){$safe=array_map(static function($value){$text=(string)$value;return preg_match('/^\s*[=+\-@]/u',$text)?"'".$text:$text;},array_values($r));fputcsv($out,$safe);}fclose($out);exit;
